import re
import pandas as pd
import json

find_col = "ROWTYPE"
base_col = "ROWTYPE"
flags = 0

def wrap_pat(pat):
    p = str(pat)
    if False:
        p = r"\b" + p + r"\b"
    if False:
        p = "^" + p
    elif False:
        p = "^" + p + "$"
    return p

def first_matching_rule(text, rules):
    if text is None or (isinstance(text, float) and pd.isna(text)):
        return "{}"
    text = str(text)
    for rule in rules:
        if rule is None or not isinstance(rule, dict):
            continue
        pat = rule.get(find_col) or rule.get(find_col.replace("`", ""))
        if pat is None:
            continue
        pat = wrap_pat(pat)
        if re.search(pat, text, flags=flags):
            return json.dumps(rule)
    return "{}"

out0 = in0.copy()
rules_col = out0["_rules"]
extracted = [
    first_matching_rule(row[base_col], row[rules_col] if isinstance(row[rules_col], list) else [])
    for _, row in out0.iterrows()
]
out0["_extracted_rule"] = extracted

